// Replace placeholder offer attachments with the real ConvertAgain assets
// generated by build-real-offer-assets.py. Also walks @Дима's thread to
// stage-1 for a clean test, if such a thread exists.
//
// Run on the server:
//   cd /opt/tgbots && node scripts/swap-offer-attachments.mjs

import { readFileSync } from "node:fs";

const HOST = "http://127.0.0.1:4173";
const GROUP_ID = "grp-167e73544bc3";

let cookie = "";
async function api(method, path, body) {
  const r = await fetch(HOST + path, {
    method,
    headers: { "content-type": "application/json", cookie },
    body: body ? JSON.stringify(body) : undefined,
  });
  const setCookie = r.headers.get("set-cookie");
  if (setCookie) cookie = setCookie.split(";")[0];
  const text = await r.text();
  const json = (() => { try { return JSON.parse(text); } catch { return { raw: text }; } })();
  if (!r.ok) throw new Error(`${method} ${path} → ${r.status}: ${json.error || text.slice(0, 200)}`);
  return json;
}

await api("POST", "/api/login", { email: "admin@rs.local", password: "admin12345" });

// Wipe old attachments
const before = await api("GET", `/api/telegram/groups/${GROUP_ID}/attachments`);
console.log(`Existing attachments: ${before.attachments.length}`);
for (const att of before.attachments) {
  await api("DELETE", `/api/telegram/groups/${GROUP_ID}/attachments/${encodeURIComponent(att.id)}`);
  console.log(`  ✗ removed ${att.filename}`);
}

// Upload new
async function upload(filename, mime, diskPath) {
  const buf = readFileSync(diskPath);
  console.log(`Uploading ${filename} (${buf.length} bytes)…`);
  const r = await api("POST", `/api/telegram/groups/${GROUP_ID}/attachments`, {
    filename, mime, contentBase64: buf.toString("base64"),
  });
  console.log(`  ✓ now ${r.attachments.length} attachment(s)`);
}

await upload("convertagain_offer_card.png", "image/png", "/tmp/ca_offer_card.png");
await upload("convertagain_sales_brief.pdf", "application/pdf", "/tmp/ca_sales_brief.pdf");

console.log("\nDone. Group now ships real materials.");
